/**
 * scenario → 驗收載體的對照表 **與它的守衛**。
 *
 * ## 為什麼要有它，以及為什麼它自己需要守衛
 *
 * 這個 repo 已經**六次**犯同一個錯：「補一條 scenario」與「覆蓋一條 scenario」是兩個動作。
 * 上一次的處置是手工做一張 82 列的對照表 —— 然後把 39 條既有 scenario **憑印象**填成
 * 「既有」，事後逐條核對發現**其中 4 條是假的**。
 *
 * 因此這份表由兩道機械守衛釘住：
 *
 * 1. **每一條 `#### Scenario:` 在表上恰有一列** —— 新增 scenario 時自動生效。
 * 2. **每一個載體標籤在原始碼中恰有一處命中** —— 填「某某測試」時必須真的有那個名字。
 *
 * ## 兩欄比「哪支探針哪條斷言」值錢
 *
 * - `greenIfAbsent`：**若實作完全沒做這件事，這條會不會照樣綠？** 答案為 `true` 的列，
 *   其鑑別力不在斷言本身 —— 它必須另有交代（換載體／由對照組承擔／老實填無載體）。
 * - `mutation`：**使它變紅的那個刻意的錯誤實作。** 沒有它，「跑一次對照組」就是一次創作，
 *   而創作出來的 mutation 很容易是一個改不到東西的 mutation。
 */
import assert from 'node:assert/strict'
import { readFileSync, readdirSync } from 'node:fs'
import { dirname, join, relative } from 'node:path'
import test from 'node:test'
import { fileURLToPath } from 'node:url'

const repoRoot = join(dirname(fileURLToPath(import.meta.url)), '..')

/**
 * 這份表涵蓋的 change。
 *
 * **一般化過了**：第一版寫死 `agent-intake-inbox`，於是下一個 change 的 scenario
 * 不在掃描範圍內 —— 那道「每一條 scenario 在表上恰有一列」的守衛會**對它完全沉默**，
 * 而那正是這整份表要防的事。
 */
const COVERED_CHANGES = [
  'agent-intake-inbox',
  'slack-mention-intake',
  'slack-rate-limit-backoff',
  'intake-badge-and-notify',
  'agent-initiated-handoff',
  'ui-language-switch',
  'handoff-body-limit-and-rejection-visibility',
  'handoff-outbox-watch-survives-restore',
  'task-completion-dimming',
  'intake-inbox-usability',
  'handoff-lineage',
  'handoff-session-lifecycle',
  'open-source-mit',
  'quick-open-nested-worktree-entry',
  'intake-periodic-rescan',
    'change-view-keyboard',
  'session-hibernation',
  'maximize-panel-and-confirm-close',
  'project-website',
  'spek-on-the-website',
  'macos-dmg-packaging',
  'spek-demo-on-the-website',
  'mobile-remote-bridge',
  'companion-test-fixes',
  'remote-prompts-attachments-rename',
  'remote-hibernate-close',
  'agent-session-control',
  'remote-close-offer',
  'remote-openspec-browse',
  'session-wait-indicator',
  'settings-sections',
  'remote-background-tasks',
  'scheduled-handoff',
  'remote-prefill-send',
  'remote-phone-context',
  'recurring-handoff',
]

/** change 的所在 —— 封存後它會搬到 `archive/` 之下，兩處都找。 */
function specRoots() {
  const changes = join(repoRoot, 'openspec', 'changes')
  const archived = readdirSync(join(changes, 'archive'), { withFileTypes: true }).filter((entry) =>
    entry.isDirectory(),
  )
  const candidates = COVERED_CHANGES.flatMap((name) => [
    join(changes, name, 'specs'),
    ...archived
      .filter((entry) => entry.name.endsWith(name))
      .map((entry) => join(changes, 'archive', entry.name, 'specs')),
  ])
  return candidates.filter((dir) => {
    try {
      readdirSync(dir)
      return true
    } catch {
      return false
    }
  })
}

export function scenariosOf(root) {
  const found = []
  const walk = (dir) => {
    for (const entry of readdirSync(dir, { withFileTypes: true })) {
      const full = join(dir, entry.name)
      if (entry.isDirectory()) walk(full)
      else if (entry.name === 'spec.md') {
        for (const line of readFileSync(full, 'utf8').split('\n')) {
          if (line.startsWith('#### Scenario:')) found.push(line.slice('#### Scenario:'.length).trim())
        }
      }
    }
  }
  walk(root)
  return found
}

